SELECT 'departments' AS item, COUNT(*) AS count FROM departments WHERE abbreviation IN ('GI','GM','GE')
UNION ALL SELECT 'department_admins', COUNT(*) FROM users WHERE username REGEXP '^admin[0-9]+$'
UNION ALL SELECT 'groups', COUNT(*) FROM student_groups WHERE abbreviation LIKE 'DUM_%'
UNION ALL SELECT 'students', COUNT(*) FROM users WHERE username REGEXP '^2021[0-9]{3}$'
UNION ALL SELECT 'teachers', COUNT(*) FROM users WHERE username REGEXP '^teacher[0-9]+$'
UNION ALL SELECT 'modules', COUNT(*) FROM modules WHERE abbreviation LIKE 'DUM_%';
